const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');
const memoryPath = path.join(userDataDir, 'memory_rules.json');

if (!fs.existsSync(userDataDir)) {
  fs.mkdirSync(userDataDir, { recursive: true });
}

if (!fs.existsSync(registryPath)) {
  fs.writeFileSync(registryPath, JSON.stringify({ trackers: {} }, null, 2), 'utf8');
}

if (!fs.existsSync(memoryPath)) {
  fs.writeFileSync(memoryPath, JSON.stringify({ morning_rules: [], custom_scopes: {} }, null, 2), 'utf8');
}

const trackersRegistry = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
const memoryRules = JSON.parse(fs.readFileSync(memoryPath, 'utf8'));

// Purge expired volatile rules automatically
const todayIsoDate = new Date().toISOString().slice(0, 10);
let memoryChanged = false;
if (memoryRules.custom_scopes && typeof memoryRules.custom_scopes === 'object') {
  for (const [scopeName, rules] of Object.entries(memoryRules.custom_scopes)) {
    if (Array.isArray(rules)) {
      const filtered = rules.filter((r) => !r.expires_at || r.expires_at >= todayIsoDate);
      if (filtered.length !== rules.length) {
        memoryRules.custom_scopes[scopeName] = filtered;
        memoryChanged = true;
      }
    }
  }
}
if (memoryChanged) {
  fs.writeFileSync(memoryPath, JSON.stringify(memoryRules, null, 2), 'utf8');
}

const body = $input.first().json.body || $input.first().json || {};
const voiceCommand = body.command || body.text || body.query || body.message || '';

return [
  {
    json: {
      voice_command: voiceCommand,
      current_date: todayIsoDate,
      current_timestamp: new Date().toISOString(),
      trackers_registry: trackersRegistry,
      memory_rules: memoryRules
    }
  }
];

const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');

let payload;
try {
  payload = typeof query === 'string' ? JSON.parse(query) : query;
} catch (err) {
  return JSON.stringify({ error: 'Invalid JSON input for create_or_update_tracker_schema', details: err.message });
}

const trackerId = String(payload.tracker_id || '').trim().toLowerCase().replace(/[^a-z0-9_]/g, '_');
if (!trackerId) {
  return JSON.stringify({ error: 'tracker_id is required' });
}

const validTypes = ['CYCLE_STATE_MACHINE', 'COLLECTION_TABLE', 'ACTIVITY_LOG'];
const trackerType = validTypes.includes(payload.type) ? payload.type : 'ACTIVITY_LOG';
const today = new Date().toISOString().slice(0, 10);

const registry = fs.existsSync(registryPath)
  ? JSON.parse(fs.readFileSync(registryPath, 'utf8'))
  : { trackers: {} };

if (!registry.trackers) registry.trackers = {};
const existing = registry.trackers[trackerId] || {};

const updatedTracker = {
  display_name: payload.display_name || existing.display_name || trackerId,
  type: trackerType,
  include_in_morning_briefing: payload.include_in_morning_briefing !== undefined
    ? Boolean(payload.include_in_morning_briefing)
    : (existing.include_in_morning_briefing !== undefined ? existing.include_in_morning_briefing : true),
  cycle_config: trackerType === 'CYCLE_STATE_MACHINE'
    ? {
        steps: Array.isArray(payload.cycle_config?.steps) && payload.cycle_config.steps.length > 0
          ? payload.cycle_config.steps
          : (existing.cycle_config?.steps || ['Step 1', 'Rest']),
        current_index: typeof payload.cycle_config?.current_index === 'number'
          ? payload.cycle_config.current_index
          : (existing.cycle_config?.current_index || 0),
        last_updated: payload.cycle_config?.last_updated || existing.cycle_config?.last_updated || today
      }
    : (payload.cycle_config || existing.cycle_config || null),
  fields_schema: Array.isArray(payload.fields_schema)
    ? payload.fields_schema
    : (existing.fields_schema || [])
};

registry.trackers[trackerId] = updatedTracker;
fs.writeFileSync(registryPath, JSON.stringify(registry, null, 2), 'utf8');

const dataFilePath = path.join(userDataDir, `data_${trackerId}.json`);
if (!fs.existsSync(dataFilePath)) {
  fs.writeFileSync(dataFilePath, JSON.stringify([], null, 2), 'utf8');
}

return JSON.stringify({
  status: 'success',
  tracker_id: trackerId,
  schema: updatedTracker,
  data_file: `data_${trackerId}.json`
});

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');

let payload;
try {
  payload = typeof query === 'string' ? JSON.parse(query) : query;
} catch (err) {
  return JSON.stringify({ error: 'Invalid JSON input for mutate_tracker_record', details: err.message });
}

const trackerId = String(payload.tracker_id || '').trim().toLowerCase().replace(/[^a-z0-9_]/g, '_');
if (!trackerId) {
  return JSON.stringify({ error: 'tracker_id is required' });
}

const registry = fs.existsSync(registryPath)
  ? JSON.parse(fs.readFileSync(registryPath, 'utf8'))
  : { trackers: {} };
const tracker = registry.trackers?.[trackerId];
if (!tracker) {
  return JSON.stringify({ error: `Tracker '${trackerId}' not found in trackers_registry.json` });
}

const dataFilePath = path.join(userDataDir, `data_${trackerId}.json`);
const records = fs.existsSync(dataFilePath)
  ? JSON.parse(fs.readFileSync(dataFilePath, 'utf8'))
  : [];

const nowIso = new Date().toISOString();
const today = nowIso.slice(0, 10);
const op = payload.operation || 'insert';

if (['advance_cycle', 'skip_or_shift_cycle', 'set_cycle_index'].includes(op)) {
  if (!tracker.cycle_config || !Array.isArray(tracker.cycle_config.steps) || tracker.cycle_config.steps.length === 0) {
    return JSON.stringify({ error: `Tracker '${trackerId}' has no valid cycle_config.steps` });
  }
  const steps = tracker.cycle_config.steps;
  const prevIndex = Number(tracker.cycle_config.current_index || 0);
  let nextIndex = prevIndex;

  if (op === 'set_cycle_index' && typeof payload.target_index === 'number') {
    nextIndex = ((payload.target_index % steps.length) + steps.length) % steps.length;
  } else {
    const delta = typeof payload.step_delta === 'number' ? payload.step_delta : 1;
    nextIndex = ((prevIndex + delta) % steps.length + steps.length) % steps.length;
  }

  tracker.cycle_config.current_index = nextIndex;
  tracker.cycle_config.last_updated = today;
  registry.trackers[trackerId] = tracker;
  fs.writeFileSync(registryPath, JSON.stringify(registry, null, 2), 'utf8');

  const logEntry = {
    id: crypto.randomUUID(),
    event: op,
    previous_step: steps[prevIndex],
    current_step: steps[nextIndex],
     ...(payload.record_data || {}),
    created_at: nowIso,
    updated_at: nowIso
  };
  records.push(logEntry);
  fs.writeFileSync(dataFilePath, JSON.stringify(records, null, 2), 'utf8');

  return JSON.stringify({
    status: 'success',
    operation: op,
    tracker_id: trackerId,
    previous_step: steps[prevIndex],
    current_index: nextIndex,
    current_step: steps[nextIndex],
    log_entry: logEntry
  });
}

if (op === 'update' && payload.record_id) {
  const idx = records.findIndex((r) => r.id === payload.record_id);
  if (idx === -1) {
    return JSON.stringify({ error: `Record '${payload.record_id}' not found in data_${trackerId}.json` });
  }
  records[idx] = {
    ...records[idx],
    ...(payload.record_data || {}),
    id: records[idx].id,
    created_at: records[idx].created_at,
    updated_at: nowIso
  };
  fs.writeFileSync(dataFilePath, JSON.stringify(records, null, 2), 'utf8');
  return JSON.stringify({ status: 'success', operation: 'update', record: records[idx] });
}

const newRecord = {
  id: crypto.randomUUID(),
  ...(payload.record_data || {}),
  created_at: nowIso,
  updated_at: nowIso
};
records.push(newRecord);
fs.writeFileSync(dataFilePath, JSON.stringify(records, null, 2), 'utf8');

return JSON.stringify({
  status: 'success',
  operation: 'insert',
  tracker_id: trackerId,
  record: newRecord
});

const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');

let payload;
try {
  payload = typeof query === 'string' ? JSON.parse(query) : query;
} catch (err) {
  return JSON.stringify({ error: 'Invalid JSON input for query_tracker_records', details: err.message });
}

const trackerId = String(payload.tracker_id || '').trim().toLowerCase().replace(/[^a-z0-9_]/g, '_');
if (!trackerId) {
  return JSON.stringify({ error: 'tracker_id is required' });
}

const registry = fs.existsSync(registryPath)
  ? JSON.parse(fs.readFileSync(registryPath, 'utf8'))
  : { trackers: {} };
const tracker = registry.trackers?.[trackerId] || null;

const dataFilePath = path.join(userDataDir, `data_${trackerId}.json`);
let records = fs.existsSync(dataFilePath)
  ? JSON.parse(fs.readFileSync(dataFilePath, 'utf8'))
  : [];

const nowMs = Date.now();
const dayMs = 24 * 60 * 60 * 1000;

if (payload.status) {
  const targetStatus = String(payload.status).toLowerCase();
  records = records.filter((r) => String(r.status || '').toLowerCase() === targetStatus);
}

if (typeof payload.older_than_days === 'number') {
  const cutoffMs = nowMs - payload.older_than_days * dayMs;
  records = records.filter((r) => {
    const refDate = Date.parse(r.updated_at || r.created_at || r.date || '');
    return !Number.isNaN(refDate) && refDate <= cutoffMs;
  });
}

if (typeof payload.recent_days === 'number') {
  const cutoffMs = nowMs - payload.recent_days * dayMs;
  records = records.filter((r) => {
    const refDate = Date.parse(r.created_at || r.updated_at || r.date || '');
    return !Number.isNaN(refDate) && refDate >= cutoffMs;
  });
}

const limit = typeof payload.limit === 'number' && payload.limit > 0 ? payload.limit : 50;
const resultRecords = records.slice(-limit);

return JSON.stringify({
  status: 'success',
  tracker_id: trackerId,
  tracker_definition: tracker,
  count: resultRecords.length,
  records: resultRecords
});

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const userDataDir = '/home/node/user_data';
const memoryPath = path.join(userDataDir, 'memory_rules.json');

let payload;
try {
  payload = typeof query === 'string' ? JSON.parse(query) : query;
} catch (err) {
  return JSON.stringify({ error: 'Invalid JSON input for update_memory_rule', details: err.message });
}

const memory = fs.existsSync(memoryPath)
  ? JSON.parse(fs.readFileSync(memoryPath, 'utf8'))
  : { morning_rules: [], custom_scopes: {} };

if (!Array.isArray(memory.morning_rules)) memory.morning_rules = [];
if (!memory.custom_scopes || typeof memory.custom_scopes !== 'object') memory.custom_scopes = {};

const op = payload.operation || 'add';
const scope = String(payload.scope || 'morning_rules').trim();
const nowIso = new Date().toISOString();

const targetArray = scope === 'morning_rules'
  ? memory.morning_rules
  : (memory.custom_scopes[scope] = Array.isArray(memory.custom_scopes[scope]) ? memory.custom_scopes[scope] : []);

if (op === 'delete') {
  const beforeLen = targetArray.length;
  const filtered = targetArray.filter((r) => r.id !== payload.rule_id && r.instruction !== payload.instruction);
  if (scope === 'morning_rules') {
    memory.morning_rules = filtered;
  } else {
    memory.custom_scopes[scope] = filtered;
  }
  fs.writeFileSync(memoryPath, JSON.stringify(memory, null, 2), 'utf8');
  return JSON.stringify({
    status: 'success',
    operation: 'delete',
    scope,
    deleted_count: beforeLen - filtered.length
  });
}

if (op === 'update' && payload.rule_id) {
  const idx = targetArray.findIndex((r) => r.id === payload.rule_id);
  if (idx === -1) {
    return JSON.stringify({ error: `Rule '${payload.rule_id}' not found in scope '${scope}'` });
  }
  targetArray[idx] = {
    ...targetArray[idx],
    instruction: payload.instruction || targetArray[idx].instruction,
    ...(scope !== 'morning_rules'
      ? {
          volatile: payload.volatile !== undefined ? Boolean(payload.volatile) : Boolean(targetArray[idx].volatile),
          expires_at: payload.expires_at !== undefined ? payload.expires_at : targetArray[idx].expires_at
        }
      : {})
  };
  fs.writeFileSync(memoryPath, JSON.stringify(memory, null, 2), 'utf8');
  return JSON.stringify({ status: 'success', operation: 'update', scope, rule: targetArray[idx] });
}

const newRule = scope === 'morning_rules'
  ? {
      id: crypto.randomUUID(),
      instruction: String(payload.instruction || ''),
      created_at: nowIso
    }
  : {
      id: crypto.randomUUID(),
      instruction: String(payload.instruction || ''),
      volatile: Boolean(payload.volatile),
      expires_at: payload.expires_at || null,
      created_at: nowIso
    };

targetArray.push(newRule);
fs.writeFileSync(memoryPath, JSON.stringify(memory, null, 2), 'utf8');

return JSON.stringify({
  status: 'success',
  operation: 'add',
  scope,
  rule: newRule
});
